+package com.example;
+
+import com.vaadin.flow.component.Key;
+import com.vaadin.flow.component.button.Button;
+import com.vaadin.flow.component.dialog.Dialog;
+import com.vaadin.flow.component.formlayout.FormLayout;
+import com.vaadin.flow.component.grid.Grid;
+import com.vaadin.flow.component.html.H1;
+import com.vaadin.flow.component.html.Span;
+import com.vaadin.flow.component.notification.Notification;
+import com.vaadin.flow.component.orderedlayout.HorizontalLayout;
+import com.vaadin.flow.component.orderedlayout.VerticalLayout;
+import com.vaadin.flow.component.textfield.EmailField;
+import com.vaadin.flow.component.textfield.TextArea;
+import com.vaadin.flow.component.textfield.TextField;
+import com.vaadin.flow.component.UI;
+import com.vaadin.flow.router.BeforeLeaveEvent;
+import com.vaadin.flow.router.BeforeLeaveObserver;
+import com.vaadin.flow.router.Route;
+import com.vaadin.flow.router.RouterLink;
+
+@Route("contact")
+public class ContactView extends VerticalLayout implements BeforeLeaveObserver {
+
+    private static final String NAME_REQUIRED = "Name is required";
+    private static final String INVALID_EMAIL = "Enter a valid e-mail address";
+    private static final String CONTACT_REQUIRED = "Give an e-mail address or a phone number";
+    private static final String MESSAGE_REQUIRED = "Message is required";
+    private static final String MESSAGE_TOO_LONG = "Message must be at most 500 characters";
+
+    private final ContactMessageStore messageStore;
+    private final TextField nameField = new TextField("Name");
+    private final EmailField emailField = new EmailField("Email");
+    private final TextField phoneField = new TextField("Phone");
+    private final TextArea messageField = new TextArea("Message");
+    private final Button sendButton = new Button("Send");
+    private final Grid<ContactMessage> messagesGrid = new Grid<>();
+
+    private boolean resettingForm;
+
+    public ContactView(ContactMessageStore messageStore) {
+        this.messageStore = messageStore;
+
+        add(new H1("Contact"));
+        add(new RouterLink("About", AboutView.class));
+
+        configureFields();
+        configureSendButton();
+
+        FormLayout form = new FormLayout(nameField, emailField, phoneField,
+                messageField, sendButton);
+        add(form);
+
+        configureGrid();
+        add(messagesGrid);
+    }
+
+    private void configureFields() {
+        nameField.setManualValidation(true);
+        emailField.setManualValidation(true);
+        phoneField.setManualValidation(true);
+        messageField.setManualValidation(true);
+
+        nameField.addValueChangeListener(event -> fieldEdited(nameField));
+        emailField.addValueChangeListener(event -> fieldEdited(emailField));
+        phoneField.addValueChangeListener(event -> fieldEdited(phoneField));
+        messageField.addValueChangeListener(event -> fieldEdited(messageField));
+    }
+
+    private void fieldEdited(com.vaadin.flow.component.HasValue<?, ?> field) {
+        if (!resettingForm) {
+            sendButton.setEnabled(true);
+            if (field == emailField || field == phoneField) {
+                emailField.setInvalid(false);
+            } else if (field instanceof TextField textField) {
+                textField.setInvalid(false);
+            } else if (field instanceof TextArea textArea) {
+                textArea.setInvalid(false);
+            }
+        }
+    }
+
+    private void configureSendButton() {
+        sendButton.setEnabled(true);
+        sendButton.addClickListener(event -> sendMessage());
+        sendButton.addClickShortcut(Key.ENTER);
+    }
+
+    private void configureGrid() {
+        messagesGrid.addColumn(ContactMessage::name).setHeader("Name");
+        messagesGrid.addColumn(ContactMessage::message).setHeader("Message");
+        messagesGrid.setItems(messageStore.getMessages());
+    }
+
+    private void sendMessage() {
+        if (!validateForm()) {
+            return;
+        }
+
+        messageStore.add(new ContactMessage(nameField.getValue(), emailField.getValue(),
+                phoneField.getValue(), messageField.getValue()));
+        messagesGrid.setItems(messageStore.getMessages());
+        Notification notification = Notification.show("Message sent");
+        if (!notification.isAttached()) {
+            UI.getCurrent().add(notification);
+        }
+
+        resettingForm = true;
+        try {
+            nameField.clear();
+            emailField.clear();
+            phoneField.clear();
+            messageField.clear();
+        } finally {
+            resettingForm = false;
+        }
+        sendButton.setEnabled(false);
+    }
+
+    private boolean validateForm() {
+        clearInvalidState();
+        boolean valid = true;
+
+        if (isBlank(nameField.getValue())) {
+            nameField.setErrorMessage(NAME_REQUIRED);
+            nameField.setInvalid(true);
+            valid = false;
+        }
+
+        String email = emailField.getValue();
+        if (!isBlank(email) && !isValidEmail(email)) {
+            emailField.setErrorMessage(INVALID_EMAIL);
+            emailField.setInvalid(true);
+            valid = false;
+        } else if (isBlank(email) && isBlank(phoneField.getValue())) {
+            emailField.setErrorMessage(CONTACT_REQUIRED);
+            emailField.setInvalid(true);
+            valid = false;
+        }
+
+        String message = messageField.getValue();
+        if (isBlank(message)) {
+            messageField.setErrorMessage(MESSAGE_REQUIRED);
+            messageField.setInvalid(true);
+            valid = false;
+        } else if (message.length() > 500) {
+            messageField.setErrorMessage(MESSAGE_TOO_LONG);
+            messageField.setInvalid(true);
+            valid = false;
+        }
+
+        return valid;
+    }
+
+    private void clearInvalidState() {
+        nameField.setInvalid(false);
+        emailField.setInvalid(false);
+        phoneField.setInvalid(false);
+        messageField.setInvalid(false);
+    }
+
+    private static boolean isBlank(String value) {
+        return value == null || value.isBlank();
+    }
+
+    private boolean isValidEmail(String value) {
+        return !emailField.getDefaultValidator().apply(value, null).isError();
+    }
+
+    private boolean hasUnsavedInput() {
+        return !isBlank(nameField.getValue()) || !isBlank(emailField.getValue())
+                || !isBlank(phoneField.getValue()) || !isBlank(messageField.getValue());
+    }
+
+    @Override
+    public void beforeLeave(BeforeLeaveEvent event) {
+        if (!hasUnsavedInput()) {
+            return;
+        }
+
+        var continueNavigation = event.postpone();
+        Dialog dialog = new Dialog();
+        dialog.setHeaderTitle("Discard your message?");
+        dialog.add(new Span("You have unsaved changes."));
+
+        Button keepEditing = new Button("Keep editing", click -> {
+            continueNavigation.cancel();
+            dialog.close();
+        });
+        Button discard = new Button("Discard", click -> {
+            dialog.close();
+            continueNavigation.proceed();
+        });
+        dialog.getFooter().add(new HorizontalLayout(keepEditing, discard));
+        dialog.open();
+    }
+}
