+package com.example;
+
+import static org.junit.jupiter.api.Assertions.assertEquals;
+import static org.junit.jupiter.api.Assertions.assertFalse;
+import static org.junit.jupiter.api.Assertions.assertTrue;
+
+import org.junit.jupiter.api.Test;
+import org.springframework.boot.test.context.SpringBootTest;
+
+import com.vaadin.browserless.SpringBrowserlessTest;
+import com.vaadin.flow.component.Key;
+import com.vaadin.flow.component.button.Button;
+import com.vaadin.flow.component.dialog.Dialog;
+import com.vaadin.flow.component.grid.Grid;
+import com.vaadin.flow.component.notification.Notification;
+import com.vaadin.flow.component.UI;
+import com.vaadin.flow.router.RouterLink;
+import com.vaadin.flow.component.textfield.EmailField;
+import com.vaadin.flow.component.textfield.TextArea;
+import com.vaadin.flow.component.textfield.TextField;
+
+@SpringBootTest(classes = Application.class)
+class ContactViewTest extends SpringBrowserlessTest {
+
+    @Test
+    void emptySubmissionShowsAllApplicableErrors() {
+        ContactView view = navigate(ContactView.class);
+        Button send = $(Button.class).withText("Send").single();
+
+        test(send).click();
+
+        assertTrue($(TextField.class, view).withLabel("Name").single().isInvalid());
+        assertEquals("Name is required",
+                $(TextField.class, view).withLabel("Name").single().getErrorMessage());
+        assertTrue($(EmailField.class).single().isInvalid());
+        assertEquals("Give an e-mail address or a phone number",
+                $(EmailField.class).single().getErrorMessage());
+        assertTrue($(TextArea.class).single().isInvalid());
+        assertEquals("Message is required", $(TextArea.class).single().getErrorMessage());
+        assertTrue(send.isEnabled());
+    }
+
+    @Test
+    void validEnterSubmissionClearsAndDisablesUntilEdited() {
+        ContactView view = navigate(ContactView.class);
+        TextField name = $(TextField.class, view).withLabel("Name").single();
+        EmailField email = $(EmailField.class).single();
+        TextArea message = $(TextArea.class).single();
+        Button send = $(Button.class).withText("Send").single();
+
+        test(name).setValue("Ada");
+        test(email).setValue("ada@example.com");
+        test(message).setValue("Hello");
+        fireShortcut(Key.ENTER);
+
+        assertEquals("", name.getValue());
+        assertEquals("", email.getValue());
+        assertEquals("", message.getValue());
+        assertFalse(send.isEnabled());
+        assertTrue(UI.getCurrent().getChildren()
+                .filter(Notification.class::isInstance)
+                .map(Notification.class::cast)
+                .anyMatch(notification -> notification.isOpened()
+                        && "Message sent".equals(notification.getElement().getProperty("text"))));
+        assertEquals(1, test($(Grid.class).single()).size());
+
+        test(name).setValue("Grace");
+        assertTrue(send.isEnabled());
+    }
+
+    @Test
+    void leavingWithInputCanBeCancelledOrConfirmed() {
+        ContactView view = navigate(ContactView.class);
+        TextField name = $(TextField.class, view).withLabel("Name").single();
+        test(name).setValue("Ada");
+
+        test($(RouterLink.class).withText("About").single()).click();
+        Dialog dialog = $(Dialog.class).single();
+        test($(Button.class, dialog).withText("Keep editing").single()).click();
+        assertTrue(getCurrentView() instanceof ContactView);
+        assertEquals("Ada", name.getValue());
+
+        test($(RouterLink.class).withText("About").single()).click();
+        test($(Button.class, $(Dialog.class).single()).withText("Discard").single()).click();
+        assertTrue(getCurrentView() instanceof AboutView);
+    }
+}
